//! Open tube: UniFFI interface, callbacks, runtime setup.
//!
//! Kotlin bindings are generated by UniFFI into `SnapFfi`; the generated
//! code loads `libsnap_ffi.so` (this crate, `crate-type = ["cdylib"]`).

/// Step 1 smoke test: hello callable from Kotlin.
#[uniffi::export]
pub fn hello() -> String {
    tracing::info!("snap-ffi hello");
    "hello from Open tube".to_string()
}

uniffi::setup_scaffolding!();
